			t.Fatal(err)
		}
		es := exportSession{
			SessionID:        s.id,
			Branch:           s.branch,
			Agent:            s.agent,
			LatestCheckpoint: s.checkpoint,
			TranscriptPath:   s.relPath,
			CreatedAt:        now.Add(-time.Hour),
		}
		if s.author != "" {
			es.Authors = []exportAuthor{{Name: s.author}}
		}
		manifestSessions = append(manifestSessions, es)
	}
