		d, err := skillDestinations("claude-code", "global", "my-skill", "/repo")
		if err != nil {
			t.Fatalf("CLAUDE_CONFIG_DIR=%q: %v", value, err)
		}
		if d[0].Path != "~/.claude/skills/my-skill/SKILL.md" {
