	}
	var withVerdict int
	db.QueryRow(`SELECT COUNT(*) FROM dossiers WHERE verdict IS NOT NULL`).Scan(&withVerdict)
	if withVerdict != 0 {
		t.Errorf("deterministic build set %d verdict(s); the verifier must only run via explicit `patterns verify`", withVerdict)
	}
}
