func resolvePatternsBrainDir(ctx context.Context, opts Options, target string) (string, error) {
	_, brainDir, err := resolvePatternsRepoAndBrain(ctx, opts, target)
	return brainDir, err
}

// resolvePatternsRepoAndBrain resolves both the local repo directory (needed as
// the agent runner's working dir) and the brain storage dir for that repo.
func resolvePatternsRepoAndBrain(ctx context.Context, opts Options, target string) (repoDir, brainDir string, err error) {
	repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
	if err != nil {
		return "", "", err
	}
	if !local {
		return "", "", fmt.Errorf("patterns require a local repository path: %s", target)
	}
	storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
	if err != nil {
		return "", "", err
	}
	return repoDir, storage.BrainDir, nil
}

func runPatternsRefresh(ctx context.Context, cmd *cobra.Command, opts Options, target string, asJSON bool) error {
	brainDir, err := resolvePatternsBrainDir(ctx, opts, target)
	if err != nil {
		return err
	}
	source, err := writeBrainEpisodesAndSource(brainDir, opts.Now().UTC())
	if err != nil {
		return err
	}
	// Explicit refresh is the stricter surface: a corpus failure is fatal here.
	if err := buildPatternCorpus(brainDir, opts.Now().UTC()); err != nil {
		return fmt.Errorf("pattern corpus: %w", err)
	}
	if asJSON {
		return writeJSON(cmd, source)
	}
	r := source.Reinforcement
	fmt.Fprintf(cmd.OutOrStdout(), "patterns: rebuilt %d episode(s) (success %d, corrected %d, neutral %d)\n",
		source.Episodes, r.Success, r.Corrected, r.Neutral)
	for _, w := range source.Warnings {
		fmt.Fprintf(cmd.ErrOrStderr(), "warning: %s\n", w)
	}
	return nil
}

// patternsStatusReport is the JSON contract for `patterns status`.
type patternsStatusReport struct {
	Present          bool                 `json:"present"`
	Freshness        string               `json:"freshness"` // current | stale | missing
	Episodes         int                  `json:"episodes"`
	Reinforcement    *reinforcementCounts `json:"reinforcement,omitempty"`
	Procedures       int                  `json:"procedures"`
	Practices        int                  `json:"practices"`
	Patterns         int                  `json:"patterns"`
	AcceptedSkills   int                  `json:"accepted_skills"`
	DeclinedPatterns int                  `json:"declined_patterns"`
	UpdatesAvailable int                  `json:"updates_available"`
	LastRun          *patternRun          `json:"last_run,omitempty"` // what the last corpus build produced
}

func runPatternsStatus(ctx context.Context, cmd *cobra.Command, opts Options, target string, asJSON bool) error {
	brainDir, err := resolvePatternsBrainDir(ctx, opts, target)
	if err != nil {
		return err
	}
	privacyPolicy, err := captureRetrievalPrivacyPolicy(brainDir)
	if err != nil {
		return err
	}
	privacyPolicy.RequireDerivedClean = true
	if err := requirePrivacyDerivedRead(brainDir); err != nil {
		return err
	}
	report, err := buildPatternsStatusReportChecked(brainDir)
	if err != nil {
		return err
	}
	return bufferRetrievalCommandOutput(cmd, []retrievalPrivacyPolicy{privacyPolicy}, func() error {
		if asJSON {
			return writeJSON(cmd, report)
		}
		if !report.Present {
			fmt.Fprintln(cmd.OutOrStdout(), "patterns: not built (run `entire brain patterns refresh`)")
			return nil
		}
		out := cmd.OutOrStdout()
		fmt.Fprintf(out, "patterns: %s\n", report.Freshness)
		fmt.Fprintf(out, "episodes: %d\n", report.Episodes)
		if r := report.Reinforcement; r != nil {
			fmt.Fprintf(out, "reinforcement: %d success, %d corrected, %d neutral\n", r.Success, r.Corrected, r.Neutral)
		}
		fmt.Fprintf(out, "procedures: %d\n", report.Procedures)
		fmt.Fprintf(out, "practices: %d\n", report.Practices)
		fmt.Fprintf(out, "accepted skills: %d\n", report.AcceptedSkills)
		fmt.Fprintf(out, "declined patterns: %d\n", report.DeclinedPatterns)
		fmt.Fprintf(out, "updates available: %d\n", report.UpdatesAvailable)
		if lr := report.LastRun; lr != nil {
			fmt.Fprintf(out, "last run: %s — %d episode(s), %d pattern(s), %d dossier(s), %d symbol link(s), %d commit(s), %d synapse(s)\n",
				lr.At, lr.Episodes, lr.Patterns, lr.Dossiers, lr.SymbolLinks, lr.Commits, lr.Synapses)
		}
		return nil
	})
}

// buildPatternsStatusReport reads the patterns source from the manifest and
// derives freshness from its recorded inputs — the sessions fingerprint and the
// tombstone epoch — via patternSourceCurrent, the same predicate the refresh
// trigger uses, so no re-extraction is required and the two cannot disagree.
// Skill-memory counts are computed by evaluating each user decision against the
// current pattern set.
func buildPatternsStatusReport(brainDir string) patternsStatusReport {
	report, _ := buildPatternsStatusReportChecked(brainDir)
	return report
}

func buildPatternsStatusReportChecked(brainDir string) (patternsStatusReport, error) {
	manifest, err := loadBrainManifest(brainDir)
	if err != nil {
		return patternsStatusReport{}, err
	}
	lastRun, hasLastRun, err := lastPatternRunChecked(brainDir)
	if err != nil {
		return patternsStatusReport{}, err
	}
	_, byID, err := loadPatternViews(brainDir)
	if err != nil {
		return patternsStatusReport{}, err
	}
	memoryRecords, err := loadBrainSkillMemory(brainDir)
	if err != nil {
		return patternsStatusReport{}, err
	}
	if manifest.Sources == nil || manifest.Sources.Patterns == nil {
		return patternsStatusReport{Present: false, Freshness: "missing"}, nil
	}
	src := manifest.Sources.Patterns
	freshness := "current"
	if !patternSourceCurrent(src, brainDir) {
		freshness = "stale"
	}
	rc := src.Reinforcement
	report := patternsStatusReport{
		Present:       true,
		Freshness:     freshness,
		Episodes:      src.Episodes,
		Reinforcement: &rc,
		Procedures:    src.Procedures,
		Practices:     src.Practices,
		Patterns:      src.Patterns,
	}
	if hasLastRun {
		report.LastRun = &lastRun
	}

	for _, rec := range memoryRecords {
		var cur *patternView
		if v, ok := byID[rec.PatternID]; ok {
			cur = &v
		}
		eval := evaluateSkillMemory(rec, cur)
		if eval.Status == skillStatusDeclined {
			report.DeclinedPatterns++
		} else {
			report.AcceptedSkills++
		}
		if eval.needsAttention() {
			report.UpdatesAvailable++
		}
	}
	return report, nil
}
func runPatternsSkillsForm(ctx context.Context, cmd *cobra.Command, opts Options, target string, s skillFormOptions) error {
	repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
	if err != nil {
		return err
	}
	if !local {
		return fmt.Errorf("patterns skills form requires a local repository path: %s", target)
	}
	storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
	if err != nil {
		return err
	}
	brainDir := storage.BrainDir
	privacyPolicy, err := captureRetrievalPrivacyPolicy(brainDir)
	if err != nil {
		return err
	}
	privacyPolicy.RequireDerivedClean = true
	if err := requirePrivacyDerivedRead(brainDir); err != nil {
		return err
	}
	return runPrivacyLinearizedPatternMutation(cmd, []retrievalPrivacyPolicy{privacyPolicy}, func() error {
		var cand *taskCandidate
		var deep *deepSkillInput
		// A theme skill is synthesized from the verified latent practice (its agent
		// description), not a raw intent_sig.
		if strings.HasPrefix(s.taskID, "theme:") {
			in, ok, err := loadAcceptedThemeAsDeepChecked(brainDir, s.taskID)
			if err != nil {
				return err
			}
			if !ok {
				return fmt.Errorf("no accepted theme %q: run `entire brain patterns verify --themes` first", s.taskID)
			}
			deep = &in
			cand = &taskCandidate{ID: s.taskID, Label: in.rec.Title}
			agent := s.agent
			if agent == "" || agent == "auto" {
				agent = defaultRefreshAgent(ctx, opts.Runner, repoDir)
			}
			if agent == "none" {
				return fmt.Errorf("skill synthesis requires an agent (codex or claude-code); none found on PATH")
			}
			return synthesizeAndForm(ctx, cmd, *cand, deep, nil, brainDir, repoDir, agent, defaultDistillAgentRunner(agent), s, opts.Now().UTC())
		}
		// Knowledge-sourced skills (procedure lessons / capability conventions) are
		// stored as accepted deep dossiers under their own ids — synthesize by
		// converting the verified record.
		if strings.HasPrefix(s.taskID, "lesson:") || strings.HasPrefix(s.taskID, "convention:") {
			in, ok, err := loadAcceptedDeepDossierChecked(brainDir, s.taskID)
			if err != nil {
				return err
			}
			if !ok {
				channel := "--lessons"
				if strings.HasPrefix(s.taskID, "convention:") {
					channel = "--conventions"
				}
				return fmt.Errorf("no accepted proposal %q: run `entire brain patterns verify %s` first", s.taskID, channel)
			}
			deep = &in
			cand = &taskCandidate{ID: s.taskID, Label: in.rec.Title, Support: in.rec.EvidenceEpisodes}
			agent := s.agent
			if agent == "" || agent == "auto" {
				agent = defaultRefreshAgent(ctx, opts.Runner, repoDir)
			}
			if agent == "none" {
				return fmt.Errorf("skill synthesis requires an agent (codex or claude-code); none found on PATH")
			}
			return synthesizeAndForm(ctx, cmd, *cand, deep, nil, brainDir, repoDir, agent, defaultDistillAgentRunner(agent), s, opts.Now().UTC())
		}
		c, corpusBacked, err := corpusTaskCandidateByIDChecked(brainDir, s.taskID)
		if err != nil {
			return err
		}
		if corpusBacked {
			cand = c
			// Corpus-backed skills MUST come from a verified deep dossier — never
			// silently from shallow corpus rows.
			if in, ok, err := loadAcceptedDeepDossierChecked(brainDir, s.taskID); err != nil {
				return err
			} else if ok {
				deep = &in
			} else {
				return fmt.Errorf("needs deep verification first: %s has no accepted deep dossier.\n"+
					"Run `entire brain patterns verify --deep` (explicit, egress-gated), then re-run this form.", s.taskID)
			}
		} else {
			// Legacy fallback for repos without a V2 corpus.
			tasks, err := loadBrainTasks(brainDir)
			if err != nil {
				return err
			}
			for i := range tasks {
				if tasks[i].ID == s.taskID {
					cand = &tasks[i]
					break
				}
			}
		}
		if cand == nil {
			return fmt.Errorf("task candidate not found: %s (run `entire brain patterns skills`)", s.taskID)
		}

		agent := s.agent
		if agent == "" || agent == "auto" {
			agent = defaultRefreshAgent(ctx, opts.Runner, repoDir)
		}
		if agent == "none" {
			return fmt.Errorf("skill synthesis requires an agent (codex or claude-code); none found on PATH")
		}
		return synthesizeAndForm(ctx, cmd, *cand, deep, nil, brainDir, repoDir, agent, defaultDistillAgentRunner(agent), s, opts.Now().UTC())
	})
}

