// buildPatternsStatusReport reads the patterns source from the manifest and
// derives freshness from its recorded inputs — the sessions fingerprint and the
// tombstone epoch — via patternSourceCurrent, the same predicate the refresh
// trigger uses, so no re-extraction is required and the two cannot disagree.
// Skill-memory counts are computed by evaluating each user decision against the
// current pattern set.
func buildPatternsStatusReport(brainDir string) patternsStatusReport {
	report, _ := buildPatternsStatusReportChecked(brainDir)
	return report
}

func buildPatternsStatusReportChecked(brainDir string) (patternsStatusReport, error) {
	manifest, err := loadBrainManifest(brainDir)
	if err != nil {
		return patternsStatusReport{}, err
	}
	lastRun, hasLastRun, err := lastPatternRunChecked(brainDir)
	if err != nil {
		return patternsStatusReport{}, err
	}
	_, byID, err := loadPatternViews(brainDir)
	if err != nil {
		return patternsStatusReport{}, err
	}
	memoryRecords, err := loadBrainSkillMemory(brainDir)
	if err != nil {
		return patternsStatusReport{}, err
	}
	if manifest.Sources == nil || manifest.Sources.Patterns == nil {
		return patternsStatusReport{Present: false, Freshness: "missing"}, nil
	}
	src := manifest.Sources.Patterns
	freshness := "current"
	if !patternSourceCurrent(src, brainDir) {
		freshness = "stale"
	}
	rc := src.Reinforcement
	report := patternsStatusReport{
		Present:       true,
		Freshness:     freshness,
		Episodes:      src.Episodes,
		Reinforcement: &rc,
		Procedures:    src.Procedures,
		Practices:     src.Practices,
		Patterns:      src.Patterns,
	}
	if hasLastRun {
		report.LastRun = &lastRun
	}

	for _, rec := range memoryRecords {
		var cur *patternView
		if v, ok := byID[rec.PatternID]; ok {
			cur = &v
		}
		eval := evaluateSkillMemory(rec, cur)
		if eval.Status == skillStatusDeclined {
			report.DeclinedPatterns++
		} else {
			report.AcceptedSkills++
		}
		if eval.needsAttention() {
			report.UpdatesAvailable++
		}
	}
	return report, nil
}
