		"offset-early": "2026-07-15T00:30:00+02:00",
		"own-fix":      "2026-07-14T20:00:00Z",
		"at-cutoff":    "2026-07-15T00:00:00Z",
		"late":         "2026-07-15T00:00:01Z",
