	switch target {
	case "all":
		order = []string{"standard", "claude-code", "codex", "factoryai-droid"}
	case "standard", "claude-code", "codex", "factoryai-droid":
		order = []string{target}
	default:
		return nil, fmt.Errorf("invalid target %q (want standard|claude-code|codex|factoryai-droid|all)", target)
	}

