	if err != nil {
		t.Fatal(err)
	}
	consolidated, err := loadBrainHistoryIndex(brainDir, manifest.Sources.History)
	if err != nil {
		t.Fatal(err)
	}
	fullRecords := canonicalHistoryRecords(t, consolidated.Records)
	if !reflect.DeepEqual(incrementalRecords, fullRecords) {
