		Version: "test",
		Env:     EntireEnv{RepoRoot: repoDir, PluginDataDir: t.TempDir()},
		Runner:  runner,
		Now:     func() time.Time { return now },
	}
	storage, err := repoStoragePaths(context.Background(), runner, opts.Env, repoDir)
