		t.Fatalf("draft skill form omitted synthesis diagnostic: %s", stderr)
	}
	var preview struct {
		TaskID  string `json:"task_id"`
		IsSkill bool   `json:"is_skill"`
		Name    string `json:"name"`
		Skill   string `json:"skill"`
	}
